# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_apple_delegate_pid() {
    ps -A -o pid= | gawk 'NF { print $1 }'
}

_choice_boundif() {
    if [[ "$ARGC_OS" == "linux" ]]; then
        find /sys/class/net -mindepth 1 -maxdepth 1 -exec basename {} \;
    else
        ifconfig -l 2>/dev/null | tr ' ' '\n'
    fi
}

_choice_hostname() {
    gawk '!/^[[:space:]]*#/ && NF >= 2 {
        for (i = 2; i <= NF; i++) {
            if ($i ~ /^#/) break
            print $i
        }
    }' /etc/hosts 2>/dev/null
    if [[ -r "$HOME/.ssh/known_hosts" ]]; then
        gawk '!/^\|/ && NF { print $1 }' "$HOME/.ssh/known_hosts" | tr ',' '\n' | sed 's/^\[\(.*\)\]:[0-9]*$/\1/'
    fi
}

_choice_port() {
    gawk '!/^[[:space:]]*#/ && NF >= 2 {
        split($2, a, "/")
        if (a[1] !~ /^[0-9]+$/) next
        printf "%s\t%s/%s\n", a[1], $1, a[2]
    }' /etc/services 2>/dev/null
}

_choice_proxy_address() {
    _argc_util_mode_kv :
    if [[ -z "$argc__kv_prefix" ]]; then
        _choice_hostname | _argc_util_transform suffix=: nospace
    else
        _choice_port
    fi
}

_choice_source_ip_address() {
    if [[ "$ARGC_OS" == "linux" ]]; then
        ip -o addr show 2>/dev/null | gawk '{ print $4 }' | cut -d/ -f1
    else
        ifconfig 2>/dev/null | gawk '/[[:space:]]inet[[:space:]]/ { print $2 }'
    fi
}
